export interface PaperInfo { name: string; marks: number; duration: string; }
export interface StrandMeta {
  section: string;        // paper/section where this strand is examined
  markWeight: number;     // approx % of total exam marks this strand can occupy
  examFrequency: number;  // 1-10 (10 = appears every year)
  difficulty: number;     // 1-5 (5 = very hard)
  studyHours: number;     // estimated hours to study thoroughly
  tip: string;            // one specific exam-savvy tip
}
export interface SubjectMeta {
  totalMarks: number;
  papers: PaperInfo[];
  keyAdvice: string;
  strands: Record<string, StrandMeta>;  // keyed by curriculum strand id
}

